<?php
namespace App\Notifications;
use App\Models\Payout; use App\Support\MessageTemplates; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class PayoutReleased extends Notification { use Queueable; public function __construct(public Payout $payout){} public function via(object $notifiable):array{return ['mail'];} public function toMail(object $notifiable):MailMessage { $p=$this->payout; $t=MessageTemplates::get('payout_released','Approved — ₹{{amount}} on the way','₹{{amount}} has been released from escrow. Reference: {{uid}}.',['amount'=>number_format($p->amount),'uid'=>$p->uid]); return (new MailMessage)->subject($t['subject'])->greeting('Your work was approved.')->line($t['body'])->line($p->available_at&&$p->available_at->isFuture()?'It clears on '.$p->available_at->format('d M, H:i').'.':'It is in the payout queue now.')->action('Open your studio',route('creator.dashboard')); } }
